const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const year = 2004;
  const startDate = ee.Date.fromYMD(year, 1, 1);
  const endDate = ee.Date.fromYMD(year, 12, 31);

  // Death Valley specific coordinates (a point within the park)
  const deathValley = ee.Geometry.Point([-116.825, 36.467]);

  // Define a global geometry for worldwide max LST calculation
  const globalGeometry = ee.Geometry.Rectangle([-180, -90, 180, 90], null, false);

  // 2. Data Acquisition & Check
  let modisLST = ee.ImageCollection('MODIS/061/MOD11A2')
    .filterDate(startDate, endDate)
    .select('LST_Day_1km'); // Select daytime LST band

  // Check if collection is empty
  let collectionSize = await modisLST.size().getInfo();
  if (collectionSize === 0) {
    console.log(`MODIS LST collection for ${year} is empty.`);
    console.log("C1");
    return;
  }
  console.log(`Initial MODIS Images for ${year}: ${collectionSize}`);

  // Function to convert LST from Kelvin*0.02 to Celsius
  const toCelsius = (image) => {
    // Apply scaling factor and convert to Celsius
    return image.multiply(0.02)
      .subtract(273.15)
      .copyProperties(image, ['system:time_start']);
  };

  // Apply conversion to the entire collection
  modisLST = modisLST.map(toCelsius);

  // 3. Calculate Death Valley's maximum daytime LST
  // Reduce the collection to find the maximum LST value over the year for Death Valley
  let deathValleyMaxImage = modisLST.max();

  // Get the maximum pixel value within Death Valley
  // Use a slightly larger scale for point reduction to ensure pixel coverage
  let dvMaxLST = await deathValleyMaxImage.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: deathValley,
    scale: 1000, // MODIS resolution is 1km, so 1000m scale is appropriate
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  if (dvMaxLST === null || dvMaxLST === undefined) {
    console.log("Calculation of Death Valley Max LST failed or resulted in no data.");
    // Check if the individual images had valid pixels first
    const dvPixelCount = await modisLST.first().select('LST_Day_1km').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: deathValley,
      scale: 1000,
      maxPixels: 1e9
    }).get('LST_Day_1km').getInfo();
    if (dvPixelCount === 0) {
      console.log("No valid pixels in Death Valley after processing.");
      console.log("C2");
    } else {
      console.log("C3"); // Calculation failure, but pixels exist.
    }
    return;
  }
  console.log(`Death Valley Max LST (${year}): ${dvMaxLST.toFixed(2)} °C`);

  // 4. Calculate Global maximum daytime LST
  // This is computationally intensive. We will map a max reducer over each image.
  // Then take the maximum of these global maxes.
  // Use a larger scale for global reduction to prevent memory issues.
  const globalMaxReducer = ee.Reducer.max();
  const globalMaxLSTs = modisLST.map(image =>
    image.reduceRegion({
      reducer: globalMaxReducer,
      geometry: globalGeometry,
      scale: 10000, // Use a larger scale for global reduction (e.g., 10km)
      maxPixels: 1e13 // Allow for a very large number of pixels
    }).get('LST_Day_1km')
  );

  // Get the maximum value from the list of global maximums
  let worldMaxLST = await globalMaxLSTs.reduce(ee.Reducer.max()).getInfo();

  if (worldMaxLST === null || worldMaxLST === undefined) {
    console.log("Calculation of Global Max LST failed or resulted in no data.");
    console.log("C3");
    return;
  }
  console.log(`Global Max LST (${year}): ${worldMaxLST.toFixed(2)} °C`);

  // 5. Validation & Final Answer
  if (dvMaxLST === null || worldMaxLST === null) {
    console.log("C3"); // One of the values is null, indicating a calculation failure.
  } else if (dvMaxLST >= worldMaxLST) { // Use >= because it "recorded the highest"
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
